def list_python_candidates() -> list[str]:
    """Prefer the Kaggle TPUVM interpreter that ships with torch_xla."""
    override = os.getenv("KRONOS_PYTHON", "").strip()
    ordered = [
        override,
        "/usr/local/bin/python",
        "/usr/local/bin/python3",
        sys.executable,
        "/usr/bin/python3",
        "/usr/bin/python",
    ]
    candidates: list[str] = []
    for candidate in ordered:
        if candidate and candidate not in candidates and Path(candidate).is_file():
            candidates.append(candidate)
    return candidates


def python_imports_torch_xla(python: str) -> bool:
    probe = subprocess.run(
        [python, "-c", "import torch_xla"],
        capture_output=True,
        text=True,
    )
    return probe.returncode == 0


def resolve_training_python(*, require_xla: bool) -> str:
    candidates = list_python_candidates()
    if not candidates:
        raise SystemExit("No Python interpreter found for TPU training")
    if not require_xla:
        return candidates[0]
    for python in candidates:
        if python_imports_torch_xla(python):
            print(
                {
                    "phase": "resolve_training_python",
                    "python": python,
                    "torch_xla": True,
                },
                flush=True,
            )
            return python
    raise SystemExit(
        "TPU training requires torch_xla, but none of these interpreters "
        f"could import it: {candidates}. This usually means the session is on "
        "the regular CPU docker image instead of "
        f"{EXPECTED_TPUVM_DOCKER_IMAGE}. Pin docker_image and "
        "machine_shape=TpuV5E8 in kernel-metadata.json, then re-push."
    )


def assert_tpu_accelerator_present(python: str | None = None) -> None:
    """Refuse to start XLA training on a CPU-only Kaggle session."""
    python = python or os.environ.get("KRONOS_PYTHON", sys.executable)
    accel = sorted(Path("/dev").glob("accel*"))
    mem_total_kb = None
    meminfo = Path("/proc/meminfo")
    if meminfo.is_file():
        for line in meminfo.read_text().splitlines():
            if line.startswith("MemTotal:"):
                mem_total_kb = int(line.split()[1])
                break
    cpu_count = os.cpu_count() or 0
    mem_total_gb = None if mem_total_kb is None else round(mem_total_kb / (1024 ** 2), 1)
    tpu_env = {
        key: os.environ.get(key)
        for key in (
            "TPU_NAME",
            "TPU_WORKER_HOSTNAMES",
            "TPU_WORKER_ID",
            "KAGGLE_KERNEL_RUN_TYPE",
            "PJRT_DEVICE",
        )
        if os.environ.get(key)
    }
    xla_devices: list[str] = []
    xla_error = None
    # Use chr(10) so the -c one-liner never embeds a real newline (that caused
    # SyntaxError: unterminated string literal on the formal Chunk1 run).
    probe_code = (
        "import os; os.environ.setdefault('PJRT_DEVICE', 'TPU'); "
        "import torch_xla.core.xla_model as xm; "
        "devs = list(xm.get_xla_supported_devices('TPU') or []); "
        "print(chr(10).join(str(d) for d in devs))"
    )
    try:
        probe = subprocess.run(
            [python, "-c", probe_code],
            capture_output=True,
            text=True,
            timeout=180,
            check=False,
        )
        if probe.returncode == 0:
            xla_devices = [line.strip() for line in probe.stdout.splitlines() if line.strip()]
        else:
            xla_error = (probe.stderr or probe.stdout or "").strip()[:500]
    except Exception as exc:  # noqa: BLE001 - diagnostics only
        xla_error = f"{type(exc).__name__}: {exc}"

    report = {
        "phase": "tpu_hardware_check",
        "python": python,
        "accel_devices": [str(path) for path in accel],
        "xla_tpu_devices": xla_devices,
        "mem_total_gb": mem_total_gb,
        "cpu_count": cpu_count,
        "tpu_env": tpu_env,
        "xla_error": xla_error,
    }
    print(report, flush=True)

    if accel and xla_devices:
        return
    if len(xla_devices) >= 8:
        # Some images expose chips only through PJRT; accept a full v5e-8 topology.
        return
    if len(xla_devices) >= 1 and accel:
        return
    # Kaggle TPU VMs often have empty /dev/accel* while still being real TPU
    # hosts (high mem/cpu + PJRT/TPU worker env). Match the hw-probe heuristic
    # so a transient XLA device enumeration miss does not block training.
    tpu_vm_signals = bool(
        tpu_env.get("PJRT_DEVICE") == "TPU"
        or tpu_env.get("TPU_WORKER_HOSTNAMES")
        or tpu_env.get("TPU_NAME")
    )
    if (
        tpu_vm_signals
        and mem_total_gb is not None
        and mem_total_gb >= 100
        and cpu_count >= 32
    ):
        print(
            {
                "phase": "tpu_hardware_check_accepted",
                "reason": "real_tpu_vm_heuristic",
                "mem_total_gb": mem_total_gb,
                "cpu_count": cpu_count,
                "tpu_env_keys": sorted(tpu_env),
            },
            flush=True,
        )
        return

    raise SystemExit(
        "TPU hardware check failed; refusing to train on a CPU-only session. "
        f"accel={len(accel)} xla_devices={len(xla_devices)} "
        f"mem_gb={mem_total_gb} cpus={cpu_count}. "
        "Re-push with docker_image=python-tpuvm, machine_shape=TpuV5E8, and "
        "`kaggle kernels push --accelerator TpuV5E8`."
    )




